import sys

def main():
    data = sys.stdin.readline().strip()
    if not data:
        print("")
        print("")
        return
    s = data.split()[0]
    if s.startswith('-'):
        s = s[1:]

    evens = []
    odds = []
    for ch in s:
        if ch.isdigit():
            digit = int(ch)
            if digit % 2 == 0:
                evens.append(digit)
            else:
                odds.append(digit)

    if evens:
        print(' '.join(map(str, evens)))
    else:
        print("")

    if odds:
        print(' '.join(map(str, odds)))
    else:
        print("")

if __name__ == "__main__":
    main()
